/**
 * statics/: static abilities, continuous effects and the layer system (CR 604, 611, 613), rule hooks, cost modifiers. Owner: WP9 (layers,
 * live statics, links, characteristics), WP16 (rule hooks and cost modifiers).
 *
 * Files:
 *   statics/api.ts          this file
 *   statics/layers.ts       computeAll(s): CR 613 layer by layer across ALL objects, started-set (613.6), dependency by trial application (613.8)   (WP9)
 *   statics/live.ts         staticEffectsOf(s, chars, layer): effects generated by the CURRENT abilities of objects (611.3a); resolvedEffects(s) (611.2)   (WP9)
 *   statics/mods.ts         applyMods(chars, mods, subject): the per-layer functions                                                                     (WP9)
 *   statics/links.ts        CR 607 link store helpers; granted-pair namespaces                                                                           (WP9)
 *   statics/abilities.ts    the abilities of an object with stable keys (p:, k:, g:, r:); statics/match.ts the evaluator of filters, quantities and          (WP9, additions
 *                           conditions over the characteristics computed so far; statics/subtypes.ts the subtype classes (CR 205.3)                         to design 5.1)
 *   statics/hooks.ts        staticEffectsFor(s, action, subject): restrictions, permissions, rule mods (collected after objects, 613.10-613.11)             (WP16)
 *   statics/costmods.ts     applicableCostMods(...) for actions/cast.ts (601.2f, 118.7-118.9)                                                           (WP16)
 *   rules/characteristics.ts#getChars calls computeAll (cached per Game by a revision counter, invalidated by the mutators that matter)
 */
import type { AbilityDef, ContinuousEffectDef, FaceDownProfile, KeywordAbilityDef, Layer, Modification, ObjRef, PlayerPred, RuleAction, StaticEffect } from '../types/ability';
import type { Chars } from '../rules/characteristics';
import type { ObjectId, PlayerId } from '../types/ids';
import type { CopiableValues, GameState, AbilityRef } from '../types/state';
import type { ObjHandle } from '../types/state';

/** Chars gains these fields (rules/characteristics.ts), all computed by computeAll. */
export interface CharsAdditions {
  /** Layer 2. */
  controller: PlayerId;
  /** Printed + keyword-generated + granted abilities, with stable keys. Keys: p:<face>:<i>, k:<face>:<i>:<n>, g:<effectId>:<n>, r:basic:<C>. */
  abilities: CharAbility[];
  /** Milestone 4's `Chars.keywords`: stays, and is recomputed from `abilities` after layer 6, so granted and removed keywords are seen by every `hasKeyword` caller. */
  keywords: KeywordAbilityDef[];
  /** Layer 6 "can't have or gain" markers. */
  cantHave: string[];
  /** P/T after layers 7a-7d as decimal strings ('*' only when a CDA could not be evaluated: then the card is manual). */
  power?: string;
  toughness?: string;
}

export interface CharAbility {
  key: string;
  origin: AbilityRef['source'];
  face: number;
  /** Index in FaceDef.abilities for printed/keyword origins, -1 otherwise. */
  index: number;
  def: AbilityDef;
  /** Effect id that granted it (origin 'granted'). */
  grantedBy?: string;
  /** WP9 addition: timestamp of the granting effect (CR 613.7a: a granted static ability takes the later of this and its object's timestamp). */
  grantedAt?: number;
  /** WP9 addition: key of the ability this one was generated from (a keyword's expansion points at the keyword ability), so removing the keyword removes what it generated. */
  parent?: string;
}

/** A continuous effect ready to be applied: from a static ability (live) or from a ContinuousEffectRec (resolved). */
export interface LiveEffect {
  id: string;
  source: ObjHandle | null;
  /** The static ability that generates it (for the existence check of CR 613.8a), absent for resolved effects. */
  origin?: { source: ObjHandle; abilityKey: string; effectIndex: number };
  /** CR 613.7: statics take the source's timestamp (or the granting effect's if later, 613.7a); resolved effects their creation time (613.7b). ONE per effect. */
  timestamp: number;
  /** WP9 addition: the player "you" means for this effect (a resolved effect's controller; for a static ability the controller of its source, CR 109.5). */
  controller?: PlayerId;
  /**
   * WP9 addition: the order among effects with EQUAL timestamps, compared number by number. Static ability: [0, number of the object, timestamp of the granting effect
   * or -1 for the object's own abilities, position of the ability, index of the effect] so that an object's own effects keep their order before the granted ones when the
   * object gets a new timestamp (CR 613.7a); resolved effect: [1, number of the effect id] (a static ability's effect first, CR 613.7n; then creation order).
   */
  rank?: readonly number[];
  /**
   * WP9 addition: a resolved effect that lasts "for as long as you control <object>" (CR 611.2b). Whether `by` still controls the object is judged with the controller
   * AFTER layer 2 (CR 613.1b), so `computeAll` checks it; the effect is left out of the computation when it is no longer true.
   */
  endsUnlessControlled?: { object: ObjectId; by: PlayerId };
  /** Resolved effects that change characteristics or control carry `{ref:'fixed'}` in `affects` (CR 611.2c); statics are live (CR 611.3a). */
  effect: ContinuousEffectDef;
  // ---- M6-0 ADDITIONS (m6 design 2.5; nothing sets them before their owners land) ----
  /** M6-2: for a 1a effect, the copiable values it applies (from ContinuousEffectRec.copy via statics/live.ts#resolvedEffects, or built by the rules for a merged permanent). */
  copy?: CopiableValues;
  /** M6-2: an `asEntry` record (CR 613.2a): its mods are applied in layer 1a. */
  asEntry?: true;
  /** M6-3: the face-down profile of a rule-generated 1b effect (one per face-down permanent or spell, timestamp = the object's, CR 613.7f). */
  faceDown?: FaceDownProfile;
}

export const LAYERS: readonly Layer[] = ['1a', '1b', 2, 3, 4, 5, 6, '7a', '7b', '7c', '7d'];

/**
 * Characteristics of every relevant object, layer by layer across ALL objects (a filter in layer N sees layers < N of the others).
 * Final algorithm: design 9.2. Ships in M5 with layers 2, 4, 5, 6, 7a-7d populated and 1a, 1b, 3 present as empty hooks (M6).
 */
export type ComputeAll = (s: GameState) => Map<ObjectId, Chars>;

/**
 * What a modification needs to know about the effect it belongs to (WP9 addition): who "you" is, the source for "this creature" and "enchanted
 * creature", and the id and timestamp the abilities it grants are keyed and ordered by. Absent: the subject is its own source and controller.
 */
export interface ModContext {
  id: string;
  source: ObjectId | null;
  controller: PlayerId;
  timestamp: number;
  /** M6-0 (m6 design 2.5): the copiable values of the 1a effect being applied (M6-2). */
  copy?: CopiableValues;
  /** M6-0 (m6 design 2.5): the face-down profile of the 1b effect being applied (M6-3). */
  faceDown?: FaceDownProfile;
}

/** M6-0 (m6 design 2.5), M6-2 (statics/copy.ts): the copiable values of an object now (CR 613.2c, 707.2-707.3): all of layer 1. Pure. */
export type CopiableValuesOf = (s: GameState, id: ObjectId) => CopiableValues;
/**
 * M6-0 (m6 design 2.5), M6-3 (statics/face-down.ts): the characteristics a face-down permanent would have if it were face up (CR 702.37e, 702.168d, 708.8):
 * computed on a copy of the state in which it is face up (its 1b effect gone, its 1a copy effects kept). Pure.
 */
export type FaceUpHypothetical = (s: GameState, id: ObjectId) => Chars;
/** M6-0 (statics/layers.ts#order1a): the 1a effects that apply to an object, in the order layer 1a applies them (CR 613.8 dependency, then timestamp, CR 613.7). */
export type Order1a = (s: GameState, id: ObjectId) => readonly LiveEffect[];

/** Apply the modifications of one layer to one object's characteristics. Pure: the input is never edited, a changed copy is returned (WP9 adds the optional `fx`). */
export type ApplyMods = (c: Chars, mods: Modification[], subject: ObjectId, s: GameState, all: ReadonlyMap<ObjectId, Chars>, fx?: ModContext) => Chars;

/** CR 613.8a: does A depend on B in this layer? Trial application on a scratch copy, including "B changes whether A exists" (Blood Moon vs a land-type granter). */
export type DependsOn = (s: GameState, a: LiveEffect, b: LiveEffect, layer: Layer, all: Map<ObjectId, Chars>) => boolean;

/** All restriction/permission/rule-mod effects that apply to `subject` for `action`, in timestamp order (613.10-613.11), "can't" before "can" (101.2). */
export interface RuleQuery {
  action: RuleAction;
  subject: ObjectId | PlayerId;
  /** The other object/player of the action (the blocker for beBlocked, the spell for cast). */
  other?: ObjectId | PlayerId;
}
export type StaticEffectsFor = (s: GameState, q: RuleQuery) => StaticEffect[];

